pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    // fuzz the interface id; the reference should return true for both IERC165 and IAccessControl ids,
    // in particular for the IAccessControl id; the mutant will return false for that id.
    function testFuzz_property(bytes4 interfaceId) public {
        // keep full domain, but restrict not necessary; however ensure we actually test the IAccessControl id
        // The general property we assert: if interfaceId equals type(IAccessControl).interfaceId then supportsInterface must be true.
        // We use try/catch to observe call completion and returned boolean.

        // Only one assertion allowed below. We compute whether the call succeeded and its return value.
        bool ok = false;
        try c.supportsInterface(interfaceId) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }

        // If the fuzzer happened to supply the IAccessControl id, the reference returns true (property),
        // while the mutant (which only returns true for IERC165) will return false, causing the test to fail on the mutant.
        // We assert that whenever interfaceId == type(IAccessControl).interfaceId, supportsInterface returns true.
        if (interfaceId == type(IAccessControl).interfaceId) {
            assertTrue(ok);
        } else {
            // For other ids we don't mandate a particular value; still satisfy single-assert rule by asserting true (trivially) only when not IAccessControl.
            // But test must contain exactly one assertTrue overall — to comply, restructure: always assert that either interfaceId != IAccessControl id or ok is true.
            // (This line is unreachable because we must have exactly one assert; handled below by unified assertion.)
        }

        // Unified single assertion required: either interfaceId is not IAccessControl id, or (it is and call returned true).
        assertTrue(interfaceId != type(IAccessControl).interfaceId || ok);
    }
}

