pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IAccessControl {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // Keep domain wide; no assumptions so fuzzer may hit the IAccessControl id

        // Call supportsInterface and record whether it completed (it should always complete)
        bool ok;
        bool ret;
        try c.supportsInterface(interfaceId) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // General rule: the reference C advertises support for IERC165 and IAccessControl
        // We assert that if the queried id equals either IERC165 or IAccessControl ids then
        // supportsInterface returns true and the call does not revert.
        bytes4 id165 = type(IERC165).interfaceId;
        bytes4 idAC = type(IAccessControl).interfaceId;

        // single assertion: for these two canonical interface ids the call must succeed and return true
