        bool ok;
        try c.supportsInterface(interfaceId) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }

        // General rule: reference C returns true for IERC165.interfaceId and IAccessControl.interfaceId
        // We assert that if the queried id equals either IERC165 or IAccessControl ids, supportsInterface is true.
        bytes4 id165 = type(IERC165).interfaceId;
        bytes4 idAccess = type(IAccessControl).interfaceId;

        // If the fuzzed interfaceId equals either known supported id, the correct contract must return true.
        if (interfaceId == id165 || interfaceId == idAccess) {
            assertTrue(ok);
        } else {
            // For other ids, we make no claim; still assert true to keep single assert requirement
