            // To satisfy the requirement of exactly one assertTrue reading c, we assert a tautology
            // that depends on c: reading supportsInterface for id165 (must be true).
            bool ok165;
            try c.supportsInterface(id165) returns (bool r165) { ok165 = r165; } catch { ok165 = false; }
