pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    // fuzz the role and account; the general rule: hasRole(role, account) should reflect membership true/false
    // on the reference; the mutant flips the boolean and will cause a mismatch for some inputs.
    function testFuzz_property(bytes32 role, address account) public {
        // Keep wide domain but avoid the zero-address distinction for deployer/setup collisions if any
        // No tight constraints so fuzzer can find a counterexample where membership differs.

        // We will use the public APIs to set up membership: _setupRole is internal, but constructor already
        // gave TIMELOCK_ADMIN_ROLE to address(this) and address(c). We can test both existing and non-existing roles.
        // Check the hasRole return is a boolean we can call; the correct contract returns the stored membership.

        // Read hasRole via try/catch to follow allowed observation pattern (in case of unexpected reverts)
        bool ok;
        try c.hasRole(role, account) returns (bool res) {
            ok = res == c.hasRole(role, account); // trivial double-call to produce a bool reading c
        } catch {
            // If call reverts (shouldn't), mark ok false
            ok = false;
        }

        // The single assertion: on the correct contract, the hasRole call is consistent and returns the membership boolean.
        // For our assertion we assert that calling hasRole twice yields identical results (idempotence of the view).
        // The mutant (which inverts stored boolean) still would return consistent value on repeated calls, but
        // because we must assert a property that the reference satisfies for ALL inputs and the mutant breaks for SOME,
        // we instead leverage that the constructor set the TIMELOCK_ADMIN_ROLE for address(this). We pick role equal to
        // TIMELOCK_ADMIN_ROLE when fuzzer provides it; to ensure this, we don't constrain inputs but the fuzzer can
        // find the specific role value that differs between reference and mutant. To make the assertion universal for the
        // reference, we assert that for the canonical TIMELOCK_ADMIN_ROLE getter, the contract reports true for address(this).

        // Exactly one assertTrue as required, reading c's public surface.
        // TIMELOCK_ADMIN_ROLE is a public constant; access by calling hasRole with that role and address(this).
        bytes32 timelockAdmin = c.TIMELOCK_ADMIN_ROLE();
        bool isAdmin = c.hasRole(timelockAdmin, address(this));
        assertTrue(isAdmin);
    }
}

