pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(0, address(this), address(this)); }

    // We fuzz a role and an account to show the universal property:
    // Reference: hasRole(role, account) == stored membership boolean (true iff role was granted).
    // Mutant: returns inverted boolean; thus there exists some (role, account) where values differ.
    function testFuzz_property(bytes32 role, address account) public {
        // widen domain: role can be anything; account can be any address
        // We will use the contract's public API to set up membership and then assert that hasRole
        // reflects the membership boolean. The reference satisfies this for all inputs; the
        // mutant inverts it for some inputs (will fail the assertion found by the fuzzer).

        // Ensure deterministic actor with some ether for potential future interactions (not required here)
        vm.deal(address(this), 1 ether);

        // Initially, no arbitrary role is granted to `account` (unless account is one of the pre-granted ones).
        // We will explicitly grant the role if account is not already granted, and then check hasRole.

        bool initiallyHas;
        try c.hasRole(role, account) returns (bool v) { initiallyHas = v; } catch {
            // In practice hasRole is view and should not revert; set to false on unexpected revert
            initiallyHas = false;
        }

        // If account already has role according to hasRole, try to revoke it (if possible) to make both branches reachable.
        // But revokeRole requires onlyRole(getRoleAdmin(role)) so we cannot revoke arbitrary roles here.
        // Instead, we rely on grant via the proposers list provided at construction: address(this) and address(c)
        // were set up with TIMELOCK_ADMIN_ROLE; use that to setup the role if needed via internal API _setupRole is internal.
        // We cannot call internal functions; however constructor already set TIMELOCK_ADMIN_ROLE to address(this) and address(c).
        // The safest approach: if hasRole reports false, we attempt to grant role by calling grantRole via a caller
        // that has admin for that role. The admin role for arbitrary role may be DEFAULT_ADMIN_ROLE (0x0) or something else;
        // but in constructor _setRoleAdmin(PROPOSER_ROLE, TIMELOCK_ADMIN_ROLE) etc. not for arbitrary role.
        // To avoid requiring specific admin setup, we use a rule that must hold for all inputs even if no grant is possible:
        // After calling hasRole twice (no state change), values must be consistent, so the single assertion compares two reads.

        // Read twice to ensure hasRole is deterministic and reflects stored state (no side-effects expected).
        bool secondHas;
        try c.hasRole(role, account) returns (bool v2) { secondHas = v2; } catch { secondHas = false; }

        // The universal property we assert: two sequential hasRole queries return the same boolean (idempotence / consistency).
        // The reference contract's hasRole merely reads storage and is pure-view; repeated reads must be equal for all inputs.
        // The mutant also would still return inverted stored bool but also deterministic; however the mutant flips truth values
        // relative to stored membership. To ensure the mutant is caught, we leverage that the contract granted TIMELOCK_ADMIN_ROLE
        // to address(this) in the constructor; therefore for the specific role TIMELOCK_ADMIN_ROLE the stored membership for
        // address(this) is true in the reference implementation, but the mutant will return false — the fuzzer can choose that pair.
        // We therefore assert consistency and additionally that when role == TIMELOCK_ADMIN_ROLE and account == address(this),
        // hasRole returns true (this is the single assert required reading contract behavior). This will pass on reference and fail on mutant.

        // Single assertion requirement: exactly one assertTrue reading c's public surface.
        // Build the condition: if the fuzzed inputs match the known granted binding (TIMELOCK_ADMIN_ROLE, address(this))
        // then hasRole must be true; otherwise, fall back to asserting the two reads are equal (consistency).

        bool cond;
        bytes32 TIMELOCK_ADMIN_ROLE = c.TIMELOCK_ADMIN_ROLE();
        if (role == TIMELOCK_ADMIN_ROLE && account == address(this)) {
            // For this particular (role, account) pair, constructor granted the role to address(this);
            // the correct contract must return true for hasRole(TIMELOCK_ADMIN_ROLE, address(this)).
            bool got;
            try c.hasRole(role, account) returns (bool v) { got = v; } catch { got = false; }
            cond = got == true;
        } else {
            // For all other inputs we require hasRole to be consistent across repeated calls (no side effects).
            cond = (initiallyHas == secondHas);
        }

        assertTrue(cond);
    }
}

