pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(0, address(this), address(this)); }

    // fuzzed params: a role and an account address
    function testFuzz_property(bytes32 role, address account) public {
        // Keep domain wide. No restrictive assumes; allow any role and any account.

        // The reference contract's general property:
        //  - If we never granted 'role' to 'account', then hasRole(role, account) must be false.
        // We ensure we didn't grant by using a freshly deployed contract and not calling grantRole/_setupRole for the fuzzed inputs.
        // For safety, if the fuzzed account is the deployer or the contract itself and role equals TIMELOCK_ADMIN_ROLE
        // those might be true by constructor setup; exclude those cases so the property universally holds.

        bytes32 adminRole = c.TIMELOCK_ADMIN_ROLE();

        // Exclude the roles/accounts that constructor explicitly granted:
        // constructor granted TIMELOCK_ADMIN_ROLE to address(this) and to deployer (address(this) in this test harness)
        // Also constructor setup used the proposers/executors arrays passed as address(this) twice; to keep wide, exclude when account==address(this)
        if (account == address(this)) return;
        if (role == adminRole) return;

        // Now, for any remaining (role, account), the reference should report false because no grants were made for them.
        bool has;
        try c.hasRole(role, account) returns (bool v) {
            has = v;
        } catch {
            // hasRole is view and should not revert; if it reverts, abort this fuzz case (do not assert)
            return;
        }

        // The single assertion: reference contract must report false for these untouched (role, account) pairs.
        // The mutant that always returns true will cause this assertion to fail for some inputs (and the fuzzer will find them).
        assertTrue(!has);
    }
}

